void Perl_my_setenv(const char *name, const char *value) { int len, plen; char *buf; len = strlen(name); if(!value) value = ""; for(;;) { plen = strlen(value); buf = vb_safesysmalloc((len + plen + 2) * sizeof(char)); memcpy(buf, name, (size_t)len); buf[len] = '='; memcpy(buf + len + 1, value, (size_t)plen); buf[len + 1 + plen] = '\0'; vb_PerlEnv_putenv_putenv(buf); free(buf); return ; } }